class MemoryBlankNodePlaceholderFreshnessTest {
	@Test
	void shorthandConstructAllocatesFreshNodesPerOccurrenceAndEvaluation() {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			BNode firstStored = vf.createBNode("bnode1");
			BNode secondStored = vf.createBNode("bnode2");
			Resource iriStored = vf.createIRI("urn:iriSubject");
			connection.add(firstStored, vf.createIRI("urn:p"), vf.createLiteral("v"));
			connection.add(secondStored, vf.createIRI("urn:p"), vf.createLiteral("v"));
			connection.add(iriStored, vf.createIRI("urn:p"), vf.createLiteral("v"));

			GraphQuery query = connection.prepareGraphQuery("CONSTRUCT WHERE { _:x <urn:p> ?o }");
			Set<Statement> firstEvaluation = evaluate(query);
			Set<Resource> firstSubjects = assertFreshConstructStatements(firstEvaluation, vf, firstStored, secondStored,
					iriStored);
			Set<Statement> secondEvaluation = evaluate(query);
			Set<Resource> secondSubjects = assertFreshConstructStatements(secondEvaluation, vf, firstStored,
					secondStored, iriStored);
			assertFalse(firstSubjects.stream().anyMatch(secondSubjects::contains),
					"Repeated evaluation must allocate new blank-node identities");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void nestedTemplateReferencesAllocateFreshPlaceholdersAtEveryDepth() {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			for (int depth = 0; depth <= 3; depth++) {
				String nestedTerm = nestedTemplateTerm(depth);
				GraphQuery query = connection.prepareGraphQuery("CONSTRUCT { <urn:holder> <urn:term> " + nestedTerm
						+ " } WHERE { VALUES ?i { 0 0 } }");
				Set<BNode> firstEvaluation = freshTemplateSubjects(evaluate(query), connection.getValueFactory());
				Set<BNode> secondEvaluation = freshTemplateSubjects(evaluate(query), connection.getValueFactory());
				assertEquals(2, firstEvaluation.size(), "Each solution occurrence needs its own nested placeholder");
				assertEquals(2, secondEvaluation.size(), "Repeated evaluation must allocate placeholders again");
				assertTrue(Collections.disjoint(firstEvaluation, secondEvaluation),
						"A prepared query must not reuse nested placeholder identities across evaluations");
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void experimentalRendererPreservesFixedAndFreshNestedConstructValues() throws Exception {
		String source = "CONSTRUCT { ?b <urn:p> <<(<_:fixed> <urn:q> _:a)>> . "
				+ "_:a <urn:r> ?b } WHERE { VALUES ?row { 1 2 } BIND(BNODE(\"label\") AS ?b) }";
		var parsed = QueryParserUtil.parseGraphQuery(QueryLanguage.SPARQL, source, null);
		String rendered = new SparqlQueryRenderer().render(parsed);

		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			GraphQuery query = connection.prepareGraphQuery(rendered);
			Set<Statement> first = evaluate(query);
			Set<Statement> second = evaluate(query);
			Set<BNode> firstGenerated = assertNestedConstructValues(first, connection.getValueFactory());
			Set<BNode> secondGenerated = assertNestedConstructValues(second, connection.getValueFactory());
			assertFalse(firstGenerated.stream().anyMatch(secondGenerated::contains),
					"Fixed and generated template nodes must be allocated anew on repeated evaluation");
		} finally {
			repository.shutDown();
		}
	}

	private static Set<Statement> evaluate(GraphQuery query) {
		Set<Statement> statements = new HashSet<>();
		try (GraphQueryResult result = query.evaluate()) {
			while (result.hasNext()) {
				statements.add(result.next());
			}
		}
		return statements;
	}

	private static Set<BNode> assertNestedConstructValues(Set<Statement> statements,
			ValueFactory vf) {
		assertEquals(4, statements.size());
		BNode fixed = vf.createBNode("fixed");
		Map<BNode, BNode> constructedNodeByResultNode = new HashMap<>();
		for (Statement statement : statements) {
			if (statement.getPredicate().equals(vf.createIRI("urn:p"))) {
				BNode resultNode = assertInstanceOf(BNode.class, statement.getSubject());
				TripleTerm term = assertInstanceOf(TripleTerm.class, statement.getObject());
				assertEquals(fixed, term.getSubject());
				assertEquals(vf.createIRI("urn:q"), term.getPredicate());
				BNode constructedNode = assertInstanceOf(BNode.class, term.getObject());
				assertNotEquals(fixed, constructedNode);
				assertNotEquals(resultNode, constructedNode);
				assertTrue(constructedNodeByResultNode.put(resultNode, constructedNode) == null,
						"Each VALUES occurrence must have its own generated template node");
			}
		}
		assertEquals(2, constructedNodeByResultNode.size());
		for (Statement statement : statements) {
			if (!statement.getPredicate().equals(vf.createIRI("urn:p"))) {
				assertEquals(vf.createIRI("urn:r"), statement.getPredicate());
				BNode constructedNode = assertInstanceOf(BNode.class, statement.getSubject());
				BNode resultNode = assertInstanceOf(BNode.class, statement.getObject());
				assertEquals(constructedNodeByResultNode.get(resultNode), constructedNode,
						"The same template label must identify the nested term and statement subject");
			}
		}
		assertEquals(2, new HashSet<>(constructedNodeByResultNode.values()).size());
		Set<BNode> generated = new HashSet<>(constructedNodeByResultNode.keySet());
		generated.addAll(constructedNodeByResultNode.values());
		assertFalse(generated.contains(fixed));
		return generated;
	}

	private static String nestedTemplateTerm(int depth) {
		String term = "<<( _:fresh <urn:p> <_:fixed> )>>";
		for (int level = 1; level <= depth; level++) {
			term = "<<( <urn:outer" + level + "> <urn:contains> " + term + " )>>";
		}
		return term;
	}

	private static Set<BNode> freshTemplateSubjects(Set<Statement> statements,
			ValueFactory vf) {
		assertEquals(2, statements.size());
		Set<BNode> generated = new HashSet<>();
		for (Statement statement : statements) {
			assertEquals(vf.createIRI("urn:holder"), statement.getSubject());
			assertEquals(vf.createIRI("urn:term"), statement.getPredicate());
			assertTrue(statement.getObject() instanceof TripleTerm);
			Set<BNode> terms = new HashSet<>();
			collectBnodes(statement.getObject(), terms);
			assertEquals(2, terms.size(), "Each nested term must contain its fresh subject and fixed object");
			assertTrue(terms.remove(vf.createBNode("fixed")), "The explicit fixed reference must keep ID fixed");
			assertEquals(1, terms.size());
			BNode fresh = terms.iterator().next();
			assertNotEquals(vf.createBNode("fixed"), fresh);
			assertTrue(generated.add(fresh), "Each solution occurrence must receive a different nested subject");
		}
		return generated;
	}

	private static void collectBnodes(Value value, Set<BNode> result) {
		if (value instanceof BNode bnode) {
			result.add(bnode);
		} else if (value instanceof TripleTerm tripleTerm) {
			collectBnodes(tripleTerm.getSubject(), result);
			collectBnodes(tripleTerm.getObject(), result);
		}
	}

	private static Set<Resource> assertFreshConstructStatements(Set<Statement> statements,
			ValueFactory vf, Resource... storedSubjects) {
		assertEquals(3, statements.size());
		Set<Resource> subjects = new HashSet<>();
		for (Statement statement : statements) {
			assertEquals(vf.createIRI("urn:p"), statement.getPredicate());
			assertEquals(vf.createLiteral("v"), statement.getObject());
			assertTrue(statement.getSubject() instanceof BNode,
					"Shorthand CONSTRUCT labels must create blank nodes for result occurrences");
			assertTrue(subjects.add(statement.getSubject()), "Each solution occurrence must have a distinct subject");
		}
		for (Resource storedSubject : storedSubjects) {
			assertFalse(subjects.contains(storedSubject), "Constructed subjects must not reuse matched input subjects");
		}
		return subjects;
	}
}
